    ("2026-05-28", "🚀 跳空上漲收 NT$2,320（+0.87%）續創 52 週新高；台北兆元宴黃仁勳會魏哲家、張忠謀","5/28 Thu 台股 2330 跟進 NYSE TSM 5/27 +1.89% 大漲訊號跳空開高、開 NT$2,310、盤中觸 NT$2,355、實際收 NT$2,320（+20，+0.87% vs 5/27 NT$2,300）；NYSE TSM 5/28 連 2 日創史高收 $424.86（+0.50% vs 5/27 $422.73）盤中觸 $425.06；ADR 溢價自 +11.7% 擴大至 +13.4%；5/28 三大法人合計大幅買超 +28,500 張；📅 5/28 晚台北兆元宴：黃仁勳會見 TSMC 董事長魏哲家與創辦人張忠謀、強化合作關係","#9E9E9E"),
