    ("2026-06-08", "📉 台股跳空補跌實際收 NT$2,305（-2.54%）；NYSE TSM 6/8 反彈 +2.80% 收 $426.80 領先止跌","6/8 Mon 台股 2330 跳空補跌反映 NYSE 6/5 -6.69% 崩跌：實際收 NT$2,305（-60，-2.54% vs 6/5 NT$2,365）、開盤跳空 -135 點 -5.70% 至 NT$2,230、盤中區間 NT$2,230-2,320 量約 52,000 張、市值回落 NT$59.8 兆；✅ 跳空後盤中快速回升 +75 點顯示低接買盤湧現、跌幅 -2.54% 低於 NYSE 6/5 崩跌 -6.69%；NYSE TSM 6/8 反彈 +2.80% 收 $426.80（+$11.63 vs 6/5 $415.17）消化 Broadcom 利空、領先確認止跌訊號；6/8 估三大法人合計賣超 -20,800 張（外資 -18,500、投信 -1,500、自營 -800）；台美 ADR 溢價自 +9.04% 大幅擴大至 +14.99%；技術面 RSI 48 跌破中軸、MACD +0.3 紅柱動能轉弱、KDJ J 急殺至 10 接近超賣","#FFCDD2"),
