    ("2026-06-10", "⚠️ TSMC 5 月營收創高 NT$4,169.75 億（+30.1% YoY）但利多出盡、台股 -2.17%、ADR 重挫 -4.47%","6/10 Wed TSMC 正式公布 5 月合併月營收 NT$4,169.75 億（NT$416.975 億元、US$13.17B）：年增 +30.1%、月增 +1.5%、創史上單月新高（超越 3 月與 4 月前高）；1-5 月累計 NT$1.96 兆、年增 +30%；分析師認為公司 well-positioned 達成 Q2 指引、可望挑戰單季營收新高（超越前高 NT$1.23 兆）；⚠️ 然而股價利多出盡：台股 2330 收 NT$2,255（-50，-2.17% vs 6/9 NT$2,305）放量 42,439 張、市值回落 NT$58.5 兆；NYSE TSM 重挫 -4.47% 收 $408.75（-$19.14）、盤中 $407.70-$426.32——sell-the-news + 半導體類股回檔共振；💰 TSMC CFO 同日暗示先進製程續漲價（3nm H2 漲 15%、sub-5nm 漲 5-10%）；⭐ 中長線基底未變：2nm 量產 70-80% 良率、AGM CEO Wei 確認 AI 需求超供應、NVIDIA $150B/年投資、Intel 確認長期夥伴、PwC 全球市值排名第 9","#FFCDD2"),
    ("2026-06-11", "✅ 台股收平 NT$2,250；NYSE TSM 強勢反彈 +3.20% 收 $421.07；外資賣壓大幅收斂、投信自營轉買","6/11 Thu 台股 2330 實際收 NT$2,250（持平 vs 6/10）、量縮整理；🏆 NYSE TSM 6/11 強勢反彈 +3.20% 收 $421.07（+$12.32 vs 6/10 $408.75），消化 6/10 -4.48% sell-the-news 賣壓、record-revenue 基本面（5 月營收 NT$4,169.75 億、+30.1% YoY、創單月新高）獲市場重新確認；Taipei Times 確認 record revenue、CEO C.C. Wei 重申「全球半導體供應將數年內持續落後 AI 需求」、Q2 月產能 160K-175K 片；⚠️ 籌碼面（真實數據）：外資 6/11 賣超 -4,904 張（自 6/10 -15,543 大幅收斂）、投信轉買 +600、自營轉買 +340，外資連 3 日賣超但拋售動能趨緩；💰 TSMC CFO 確認 3nm H2 漲 ~15%、sub-5nm 漲 5-10%","#C8E6C9"),
