    ("2026-07-02", "📉 台股補跌兌現、惟相對抗跌守穩 NT$2,450", "7/2 Thu 台股 2330 官方收 NT$2,465（-40、-1.60%、量約 35,000 張）跟進 NYSE 7/1 夜盤重挫 -6.98% 補跌、終結連 3 漲；⭐ 惟跌幅遠小於美股、守穩 NT$2,450 心理整數支撐、相對抗跌，顯示補跌壓力大致釋放；NYSE 7/1 收 $444.23 為最新確認收盤、7/2 美股盤待今晚；📊 ADR 溢價自 +10.13% 微升至 +11.91%；7/2 估三大法人合計賣超（外資估 -8,000 張）；🎯 中長線基底未變：NVIDIA #1 客戶/A16 首發、Vera Rubin 6 顆晶片全 TSMC 代工、2nm 70-80% 良率、Nomura 目標 NT$3,425",  "#FFF9C4"),
    ("2026-07-03", "⚖️ 台股止穩、NYSE 國慶休市", "7/3 Fri 台股 2330 官方收 NT$2,445（-20、-0.81% vs 7/2 NT$2,465、量 26,455 張、開 2,415/高 2,465/低 2,415）跌幅較 7/2 收斂、守穩 NT$2,410；NYSE TSM 7/3 因美國國慶（7/4 週六順延）休市，最新確認收盤為 7/2 $434.16（-2.27%、前收 7/1 $444.23、連二跌但跌幅收斂）；🚀 Barclays 上調目標至 $625",  "#C8E6C9"),
    ("2026-07-06", "🚀 NYSE V 型大反彈、台股翻紅", "7/6 Mon NYSE TSM 假期後重新開盤即大漲 +4.06% 收 $451.79（+$17.63、前收 7/2 $434.16、stockanalysis.com 確認）收復 7/1-7/2 全數跌幅、費半 SOX +3.92%、AI 半導體回神；台股 2330 7/6 官方收 NT$2,460（+15、+0.61%）連二跌後翻紅、盤中高觸 NT$2,500；🤝 NVIDIA-SK 海力士宣布多年期記憶體合作；⭐ 漲價題材 + Barclays $625 / Nomura NT$3,425 續撐",  "#C8E6C9"),
    ("2026-07-07", "📉 台股 7/7 官方收 NT$2,440（-0.81%）【7/9 更正】、Citi 上調目標至 NT$3,800", "7/7 Tue 台股 2330 官方收 NT$2,440（-20、-0.81% vs 7/6 NT$2,460、開 2,480／盤中高 NT$2,500／低 2,440、量 31,401 張、TWSE 官方）——盤初跟進 Citi 升評與 NYSE 7/6 +4.06% 反彈開高觸 2,500、尾盤翻黑收最低；⚠️【7/9 更正】本欄原誤載收 NT$2,490（+1.22%）、外資買超 +12,000 張，經 TWSE 官方核實更正為收 NT$2,440、三大法人合計 +385 張（外資 +83／投信 +539／自營 -237）；🚀 Citi（花旗）7/6 大幅上調 TSMC 台股目標價自 NT$2,875 至 NT$3,800（+32%、維持買入）仍為本日最大利多；NYSE TSM 7/7 收 $432.57（-4.25%）",  "#FFF9C4"),
